import os, ast, json
from pathlib import Path

inputs = Path('/inputs')
work = Path('/work/layout.json')

# read inert reference text
_ = (inputs/'smell-catalog.md').read_text(encoding='utf-8')

# collect included files top-level py excluding rules
py_files = []
for p in sorted(inputs.iterdir(), key=lambda x: x.name):
    if p.is_file() and p.suffix == '.py':
        n = p.name
        if n == '__init__.py' or n.startswith('test_') or n.endswith('_test.py'):
            continue
        py_files.append(p)

siblings = {p.stem: p.name for p in py_files}

# line counts
line_counts = {}
texts = {}
for p in py_files:
    t = p.read_text(encoding='utf-8')
    texts[p.name] = t
    line_counts[p.name] = len(t.splitlines())

# import extraction
imports_map = {p.name:set() for p in py_files}

for p in py_files:
    t = texts[p.name]
    try:
        tree = ast.parse(t, filename=str(p))
    except SyntaxError:
        # if syntax error, skip imports extraction for this file
        tree = None
    if tree is None:
        continue
    cur_stem = p.stem
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for alias in node.names:
                name = alias.name
                pref = 'skillc.frontend'
                if name == pref or name.startswith(pref + '.'):
                    rest = name[len(pref):].lstrip('.')
                    if rest:
                        comp = rest.split('.')[0]
                        if comp in siblings and comp != cur_stem and comp != '__init__':
                            imports_map[p.name].add(siblings[comp])
        elif isinstance(node, ast.ImportFrom):
            level = node.level or 0
            module = node.module
            if level == 1:
                if module:
                    comp = module.split('.')[0]
                    if comp in siblings and comp != cur_stem and comp != '__init__':
                        imports_map[p.name].add(siblings[comp])
                else:
                    for alias in node.names:
                        an = alias.name
                        if an == '*':
                            continue
                        comp = an.split('.')[0]
                        if comp in siblings and comp != cur_stem and comp != '__init__':
                            imports_map[p.name].add(siblings[comp])
            elif level == 0:
                pref = 'skillc.frontend'
                if module == pref or (module and module.startswith(pref + '.')):
                    rest = module[len(pref):].lstrip('.') if module else ''
                    if rest:
                        comp = rest.split('.')[0]
                        if comp in siblings and comp != cur_stem and comp != '__init__':
                            imports_map[p.name].add(siblings[comp])
                    else:
                        for alias in node.names:
                            an = alias.name
                            if an == '*':
                                continue
                            comp = an.split('.')[0]
                            if comp in siblings and comp != cur_stem and comp != '__init__':
                                imports_map[p.name].add(siblings[comp])

# files list
files_rows = []
for p in sorted(py_files, key=lambda x: x.name):
    files_rows.append({
        'name': p.name,
        'lines': int(line_counts[p.name]),
        'imports': sorted(imports_map[p.name])
    })

# prefix clusters
stems = sorted([p.stem for p in py_files])
prefixes = set()
for s in stems:
    for i in range(4, len(s)+1):
        prefixes.add(s[:i])

set_to_prefixes = {}
for pref in prefixes:
    members = tuple(sorted([s for s in stems if s.startswith(pref)]))
    if len(members) >= 3:
        set_to_prefixes.setdefault(members, []).append(pref)

def lcp(strings):
    if not strings:
        return ''
    m = min(strings)
    M = max(strings)
    i = 0
    while i < len(m) and i < len(M) and m[i] == M[i]:
        i += 1
    return m[:i]

prefix_rows = []
for members in set_to_prefixes:
    pref = lcp(list(members))
    files = [siblings[s] for s in sorted(members)]
    lines = sum(line_counts[f] for f in files)
    prefix_rows.append({'prefix': pref, 'files': files, 'lines': int(lines)})
prefix_rows.sort(key=lambda r: r['prefix'])

# import tree clusters
adj = {name: set(imps) for name, imps in imports_map.items()}

cluster_rows = []
for root in sorted(adj):
    if len(adj[root]) < 3:
        continue
    seen = set()
    stack = [root]
    while stack:
        cur = stack.pop()
        if cur in seen:
            continue
        seen.add(cur)
        for nxt in adj.get(cur, ()): 
            if nxt not in seen:
                stack.append(nxt)
    if len(seen) >= 5:
        files = sorted(seen)
        lines = sum(line_counts[f] for f in files)
        cluster_rows.append({'root': root, 'files': files, 'lines': int(lines)})
cluster_rows.sort(key=lambda r: r['root'])

out = {
    'files': files_rows,
    'prefix_clusters': prefix_rows,
    'import_tree_clusters': cluster_rows,
}

work.write_text(json.dumps(out, ensure_ascii=False, separators=(',', ':')), encoding='utf-8')

print('wrote', work)
print('files', len(files_rows), 'prefix_clusters', len(prefix_rows), 'import_tree_clusters', len(cluster_rows))
print(work.read_text(encoding='utf-8'))

import json
from pathlib import Path
p=Path('/work/layout.json')
obj=json.loads(p.read_text(encoding='utf-8'))
assert list(obj.keys())==['files','prefix_clusters','import_tree_clusters']
for r in obj['files']:
    assert set(r.keys())=={'name','lines','imports'}
    assert isinstance(r['lines'], int) and not isinstance(r['lines'], bool)
for r in obj['prefix_clusters']:
    assert set(r.keys())=={'prefix','files','lines'}
    assert isinstance(r['lines'], int) and not isinstance(r['lines'], bool)
for r in obj['import_tree_clusters']:
    assert set(r.keys())=={'root','files','lines'}
    assert isinstance(r['lines'], int) and not isinstance(r['lines'], bool)
print('ok')
